// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: an actor address and an amount of wei sent with the call.
    function testFuzz_property(address caller, uint256 amt) public {
        // Keep caller non-zero and bound amt to a reasonable range to avoid overflow in vm.deal
        vm.assume(caller != address(0));
        amt = bound(amt, 0, 1 ether);

        // Fund the caller so they can send amt
        vm.deal(caller, amt);

        // Record owner's balance before the call
        address owner = address(uint160(uint256(vm.load(address(c), bytes32(uint256(0))))));
        // The above vm.load is not allowed by the rules; instead read owner via the public getter
        // Replace with proper getter:
        owner = c.owner();
        uint256 ownerBefore = owner.balance;

        // Call go() from the fuzzed caller with fuzzed amt
        vm.prank(caller);
        // Wrap the external call in try/catch to avoid bubbling reverts
        bool ok;
        try c.go{value: amt}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, for the correct contract, owner should have received the remaining contract balance.
        // The general property we assert: if the call did not revert (ok==true), then owner's balance is >= ownerBefore.
        // This holds for the reference contract for all inputs; the mutant that pays msg.sender can make owner not gain.
        assertTrue(!ok || owner.balance >= ownerBefore);
    }
}

