pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: amount to send and an initial funding for owner to observe balance change
    function testFuzz_property(uint256 sendAmount, uint256 ownerInitial) public {
        // Keep wide bounds but avoid extremely large unrealistic values
        sendAmount = bound(sendAmount, 0, 1 ether);
        ownerInitial = bound(ownerInitial, 0, 10 ether);

        // Deploy a benign receiver that will accept the forwarded call (so the external target.call succeeds)
        AcceptingReceiver receiver = new AcceptingReceiver();

        // Fund the receiver so it can forward/accept (not strictly necessary but realistic)
        vm.deal(address(receiver), 1 ether);

        // Ensure owner has some initial balance to compare against
        address owner = c.owner();
        vm.deal(owner, ownerInitial);

        // Pick a caller and fund it so it can send sendAmount
        address caller = address(0xABCD);
        vm.deal(caller, 2 ether);

        // The property we assert: when the external target call succeeds (receiver accepts),
        // after go() returns the contract's balance is zero and the owner's balance increased
        // by the leftover that was in the contract (i.e., owner gets the remaining funds).

        // To force c to call our receiver, we make the receiver address be the hardcoded target
        // used in C. We cannot change C's code, but we can trick the external call to succeed
        // by having our receiver be at that hardcoded address. Foundry allows creating contract
        // at arbitrary addresses via create2 in tests, but here we instead make the receiver
        // accept funds and then perform the call from caller to c.go with value sendAmount.
        // The important part: the external call to the target succeeds (receiver accepts), so
        // the reference contract will transfer its remaining balance to owner while mutant sends to msg.sender.

        // Record owner balance before
        uint256 ownerBefore = owner.balance;

        // Call c.go from caller sending sendAmount and ensure the external target (which resides at a fixed
        // address inside C) will accept the forwarded funds. To achieve this we deploy a Forwarder at that
        // hardcoded target address using create2. The target in original C is 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C.
        // We deploy a minimal forwarder there that forwards to our AcceptingReceiver so the low-level call succeeds.

        address targetAddress = 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;

        // Deploy Forwarder at that exact address using create2
        bytes memory bytecode = type(Forwarder).creationCode;
        bytes32 salt = bytes32(uint256(uint160(address(this))));
        address deployed;
        assembly {
            deployed := create2(0, add(bytecode, 0x20), mload(bytecode), salt)
        }
        // Initialize the forwarder to point to our receiver
        Forwarder(payable(deployed)).init(address(receiver));

        // Now call c.go as caller with sendAmount
        vm.prank(caller);
        c.go{value: sendAmount}();

        // After go() returns, reference contract should have transferred its entire balance to owner.
        // So address(c).balance == 0 and owner's balance strictly increased compared to before.
        // We assert that owner's balance is > ownerBefore. The mutant that pays msg.sender instead
        // will sometimes leave owner unchanged, causing this assertion to fail for some fuzzed inputs.
        assertTrue(owner.balance > ownerBefore);
    }
}

// Minimal forwarder deployed at the fixed target address to forward funds to the accepting receiver
contract Forwarder {
    address payable dest;
    bool inited;
    function init(address _dest) external {
        require(!inited, "init");
        dest = payable(_dest);
        inited = true;
    }
    fallback() external payable {
        // forward all gas and value to destination; ignore return
        (bool ok, ) = dest.call{value: msg.value}("");
        require(ok);
    }
}

// Accepting receiver that accepts ether
contract AcceptingReceiver {
    receive() external payable {}
}
